var minDeletions = function(s) {
    const counts = Array(26).fill(0);
    for (let i = 0; i < s.length; ++i) {
        counts[s.charCodeAt(i) - 97]++;
    }
    const used = new Set();
    let deletions = 0;
    for (let freq of counts) {
        while (freq > 0 && used.has(freq)) {
            freq--;
            deletions++;
        }
        if (freq > 0) used.add(freq);
    }
    return deletions;
};
